using System.Collections;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.TestTools;
using Game.Runtime;

public class AbilityCooldownTests
{
    private GameObject _go;
    private AbilityCooldown _cooldown;

    private AbilityCooldown Create(float duration)
    {
        _go = new GameObject("AbilityCooldown");
        _cooldown = _go.AddComponent<AbilityCooldown>();
        var so = new UnityEditor.SerializedObject(_cooldown);
        so.FindProperty("_cooldownDuration").floatValue = duration;
        so.ApplyModifiedPropertiesWithoutUndo();
        return _cooldown;
    }

    [TearDown]
    public void TearDown()
    {
        if (_go != null)
        {
            Object.DestroyImmediate(_go);
        }
    }

    [Test]
    public void Starts_Ready()
    {
        var cooldown = Create(1f);
        Assert.IsTrue(cooldown.IsReady);
    }

    [Test]
    public void TryUse_Succeeds_When_Ready_And_Starts_Cooldown()
    {
        var cooldown = Create(1f);

        bool result = cooldown.TryUse();

        Assert.IsTrue(result);
        Assert.IsFalse(cooldown.IsReady);
    }

    [Test]
    public void TryUse_Fails_When_Not_Ready()
    {
        var cooldown = Create(1f);
        cooldown.TryUse();

        bool result = cooldown.TryUse();

        Assert.IsFalse(result);
    }

    [Test]
    public void Tick_With_Zero_Remaining_Stays_Ready()
    {
        var cooldown = Create(1f);

        cooldown.Tick(0.5f);

        Assert.IsTrue(cooldown.IsReady);
    }

    [UnityTest]
    public IEnumerator Tick_Advances_Cooldown_And_Becomes_Ready_Exactly_At_Elapse()
    {
        var cooldown = Create(1f);
        cooldown.TryUse();

        cooldown.Tick(0.4f);
        Assert.IsFalse(cooldown.IsReady);
        yield return null;

        cooldown.Tick(0.4f);
        Assert.IsFalse(cooldown.IsReady);
        yield return null;

        cooldown.Tick(0.2f);
        Assert.IsTrue(cooldown.IsReady);
    }

    [Test]
    public void Tick_Does_Not_Overshoot_Below_Zero()
    {
        var cooldown = Create(1f);
        cooldown.TryUse();

        cooldown.Tick(5f);

        Assert.IsTrue(cooldown.IsReady);
        Assert.AreEqual(0f, cooldown.Remaining);
    }

    [Test]
    public void Ready_Event_Fires_Exactly_When_Cooldown_Elapses()
    {
        var cooldown = Create(1f);
        cooldown.TryUse();
        int readyCount = 0;
        cooldown.Ready += () => readyCount++;

        cooldown.Tick(0.5f);
        Assert.AreEqual(0, readyCount);

        cooldown.Tick(0.5f);
        Assert.AreEqual(1, readyCount);

        cooldown.Tick(0.1f);
        Assert.AreEqual(1, readyCount);
    }
}
